    // 1. Gambar latar gradasi (khusus mode 2D)
    const bg = scene.add.image(W / 2, H / 2, 'bg_gradient').setDepth(-100);

    // 2. Debu melayang jika mode kurangi gerakan tidak aktif dan 3D tidak aktif
